//! Lucide icon names (docs/contracts/v1-cards.md §2.4, §5; cards.md R215; D-1955, D-1958, D-1991).
//!
//! The data is the committed `packages/schema/data/lucide-0.460.0.json` (generated by `tools/icons/gen-lucide.mjs`) and
//! the hand-written aliases `packages/schema/data/icon-aliases.json`, compiled in with `include_str!` and parsed once on
//! first use. No file system, no network (AR-03, NFR-SEC-01).

use std::collections::HashMap;
use std::sync::LazyLock;

use serde_json::Value;

pub const LUCIDE_VERSION: &str = "0.460.0";

const DATA: &str = include_str!("../../../packages/schema/data/lucide-0.460.0.json");
const ALIASES: &str = include_str!("../../../packages/schema/data/icon-aliases.json");

/// One element of a Lucide icon node: the SVG tag (`path`, `circle`, `rect`, `polyline`, `line`, `polygon`,
/// `ellipse`) and its attributes (the data file's object keys, in key order: attribute order means nothing in SVG).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct IconEl {
    pub tag: String,
    pub attrs: Vec<(String, String)>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ResolvedIcon {
    /// The canonical Lucide 0.460 name.
    pub name: &'static str,
    pub node: &'static [IconEl],
}

struct Set {
    icons: HashMap<String, Vec<IconEl>>,
    aliases: HashMap<String, String>,
}

static SET: LazyLock<Set> = LazyLock::new(|| {
    let mut icons: HashMap<String, Vec<IconEl>> = HashMap::new();
    if let Ok(Value::Object(top)) = serde_json::from_str::<Value>(DATA) {
        if let Some(Value::Object(all)) = top.get("icons") {
            for (name, e) in all {
                let node: Vec<IconEl> = e
                    .get("n")
                    .and_then(Value::as_array)
                    .map(|els| {
                        els.iter()
                            .filter_map(|el| {
                                let a = el.as_array()?;
                                let tag = a.first()?.as_str()?.to_string();
                                let attrs = a.get(1)?.as_object()?.iter().map(|(k, v)| (k.clone(), v.as_str().map(str::to_string).unwrap_or_else(|| v.to_string()))).collect();
                                Some(IconEl { tag, attrs })
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                icons.insert(name.clone(), node);
            }
        }
    }
    let aliases = match serde_json::from_str::<Value>(ALIASES) {
        Ok(Value::Object(m)) => m.into_iter().filter_map(|(k, v)| v.as_str().map(|t| (k, t.to_string()))).collect(),
        _ => HashMap::new(),
    };
    Set { icons, aliases }
});

/// D-1955: the name itself when it is a Lucide 0.460 name, else its alias target (§5.3); None for anything else
/// (unknown, empty, any non-ASCII character: FR-FMT-12 AC-15). Leading and trailing spaces are ignored.
pub fn resolve_icon(name: &str) -> Option<ResolvedIcon> {
    let n = name.trim();
    if n.is_empty() || !n.is_ascii() {
        return None;
    }
    let set: &'static Set = &SET;
    let found = |k: &str| set.icons.get_key_value(k).map(|(k, v)| ResolvedIcon { name: k.as_str(), node: v.as_slice() });
    found(n).or_else(|| set.aliases.get(n).and_then(|t| found(t)))
}

/// The canonical name of `name` (§2.3's "same canonical name"), else None.
pub fn canonical(name: &str) -> Option<&'static str> {
    resolve_icon(name).map(|r| r.name)
}

/// Whether two icon names are the same icon: equal as written (trimmed), or resolving to the same canonical name (D-1991).
pub fn same_icon(a: &str, b: &str) -> bool {
    a.trim() == b.trim() || matches!((canonical(a), canonical(b)), (Some(x), Some(y)) if x == y)
}

/// types.md R14's 24 names (the list `ICONS` held), kept only to test D-1955.
pub const OLD_ICON_NAMES: [&str; 24] = [
    "file-text", "check-square", "zap", "calendar", "hash", "image", "file", "book", "book-open", "lightbulb", "users", "user", "folder", "map", "star", "flag", "bookmark",
    "briefcase", "coffee", "globe", "graduation-cap", "pen-line", "utensils", "plane",
];
